// v2
import { onMounted } from 'vue'
import { usePortfolioStore } from '@/stores/portfolio'
import { useTickerCurrency, useCurrency, usePercent, gainLossClass } from '@/composables/useFormat'
import AllocationChart from '@/components/charts/AllocationChart.vue'
import TopMoversChart from '@/components/charts/TopMoversChart.vue'
import SkeletonCard from '@/components/ui/SkeletonCard.vue'

const portfolio = usePortfolioStore()

onMounted(() => portfolio.fetchPortfolio())
</script>

<template>
  <div class="dashboard">
    <header class="dash-header">
      <h1>Portfolio</h1>
    </header>

    <div v-if="portfolio.loading" class="cards-grid">
      <SkeletonCard v-for="n in 3" :key="n" />
    </div>

    <template v-else>
      <!-- Combined multi-currency total -->
      <div v-if="portfolio.totals.length > 0" class="summary-card">
        <p class="summary-label">Total Portfolio</p>
        <p class="summary-value combined-value">
          <span v-for="(t, i) in portfolio.totals" :key="t.currency">
            <span v-if="i > 0" class="plus"> + </span>
            {{ useCurrency(t.value, t.currency) }}
          </span>
        </p>
        <p class="summary-pnl combined-pnl">
          <span v-for="(t, i) in portfolio.totals" :key="t.currency" :class="gainLossClass(t.pnl)">
            <span v-if="i > 0" class="text-muted"> · </span>
            {{ t.pnl >= 0 ? '+' : '' }}{{ useCurrency(t.pnl, t.currency) }} ({{ usePercent(t.pnlPercent) }})
          </span>
        </p>
      </div>
      <div v-else class="summary-card">
        <p class="summary-label">Total Portfolio</p>
        <p class="summary-value">$0.00</p>
      </div>

      <!-- Day P&L per currency -->
      <div class="day-card" :class="gainLossClass(portfolio.totals.reduce((s,t) => s + (t.dayPnl||0), 0))">
        <span class="day-label">Today</span>
        <span class="day-value combined-day">
          <span v-for="(t, i) in portfolio.totals" :key="t.currency" :class="gainLossClass(t.dayPnl)">
            <span v-if="i > 0" class="text-muted"> · </span>
            {{ t.dayPnl >= 0 ? '+' : '' }}{{ useCurrency(t.dayPnl, t.currency) }}
          </span>
        </span>
      </div>

      <!-- Allocation donut -->
      <AllocationChart :positions="portfolio.positions" :combined-usd="portfolio.combinedUsd" />

      <!-- Top movers -->
      <section v-if="portfolio.positions.length > 1" class="section">
        <h2>Today's Movers</h2>
        <TopMoversChart :positions="portfolio.positions" />
      </section>

      <!-- Holdings list -->
      <section class="section">
        <h2>Holdings</h2>
        <div
          v-for="pos in portfolio.positions"
          :key="pos.ticker"
          class="holding-row"
          @click="$router.push(`/stock/${pos.ticker}`)"
        >
          <div class="holding-left">
            <span class="ticker">{{ pos.ticker }}</span>
            <span class="company text-muted">{{ pos.companyName }}</span>
          </div>
          <div class="holding-right">
            <span class="price">{{ useTickerCurrency(pos.currentPrice, pos.ticker) }}</span>
            <span :class="gainLossClass(pos.changePercent)" class="change">
              {{ usePercent(pos.changePercent) }}
            </span>
          </div>
        </div>
        <p v-if="!portfolio.positions.length" class="empty text-muted">
          No holdings yet. Add a transaction to get started.
        </p>
      </section>
    </template>
  </div>
</template>

